#!/usr/bin/env python3
"""Independent verification of a response against an instance.

Builds a fresh Z3 model directly from the request JSON (coefficients recomputed
by brute.prepare, which is separate code from the submission) and checks every
claim of the response semantically.
"""
import json, sys
from fractions import Fraction
sys.path.insert(0, '/workspace/tmp')
from brute import prepare
import z3


def build(inst, k):
    P = prepare(inst)
    C, E, S, K = P['C'], P['E'], P['S'], P['K']
    link = P['link']; cap = P['cap']; obs = P['obs']
    q = [[z3.Int('q%d_%d' % (s, c)) for c in range(C)] for s in range(S)]
    base = []
    for s in range(S):
        for c in range(C):
            lo, hi = inst['snapshots'][s]['bounds'][c]
            base.append(q[s][c] >= lo); base.append(q[s][c] <= hi)
    for s in range(S):
        for e in range(E):
            terms = [link[c][e] * q[s][c] for c in range(C) if link[c][e]]
            if terms: base.append(z3.Sum(terms) <= cap[e])
    doms = {}
    for d in inst['domains']:
        doms[d] = []
    trusted = []
    for (si, coef, lo, hi, d) in obs:
        expr = (z3.Sum([co * q[si][c] for c, co in enumerate(coef) if co])
                if any(coef) else z3.IntVal(0))
        if d is None:
            trusted.append((expr, lo, hi))
        else:
            doms[d].append((expr, lo, hi))
    for (expr, lo, hi) in trusted:
        base.append(expr >= lo); base.append(expr <= hi)
    fvars = {}
    for d, lst in doms.items():
        if not lst: continue
        fb = z3.Bool('f_' + d)
        fvars[d] = fb
        conj = []
        for (expr, lo, hi) in lst:
            conj.append(expr >= lo); conj.append(expr <= hi)
        base.append(z3.Implies(z3.Not(fb), z3.And(conj)))
    fl = list(fvars.values())
    return dict(P=P, q=q, base=base, fvars=fvars, fl=fl, C=C, E=E, S=S, K=K,
                link=link)


class Bad(Exception):
    pass


def verify(inst, resp):
    """Raise Bad(reason) on any semantic problem."""
    if resp.get('id') != inst['id']:
        raise Bad('id mismatch')
    st = resp.get('status')
    if st == 'error':
        raise Bad('unexpected error response: %s' % resp.get('error'))
    M = build(inst, None)
    C, E, S, K = M['C'], M['E'], M['S'], M['K']
    q, base, fl = M['q'], M['base'], M['fl']
    sol = z3.Solver(); sol.add(base)

    def sat(extra):
        sol.push()
        for e in extra: sol.add(e)
        r = sol.check()
        sol.pop()
        if r == z3.unknown: raise Bad('z3 unknown in verifier')
        return r == z3.sat

    # ---- feasibility / min_faults -------------------------------------
    if st == 'infeasible':
        if fl:
            if sat([z3.AtMost(*(fl + [inst['max_faults']]))]):
                raise Bad('declared infeasible but a solution exists')
        else:
            if sat([]): raise Bad('declared infeasible but base is sat')
        for key in ('min_faults', 'faults', 'snapshots', 'witness'):
            if key in resp and resp[key] is not None:
                pass
        return
    k = resp['min_faults']
    if not isinstance(k, int) or k < 0 or k > inst['max_faults']:
        raise Bad('bad min_faults %r' % k)
    if fl:
        if k > 0 and sat([z3.AtMost(*(fl + [k - 1]))]):
            raise Bad('k not minimal')
        if not sat([z3.AtMost(*(fl + [k]))]):
            raise Bad('no explanation with k faults')
        sol.add(z3.AtMost(*(fl + [k]))); sol.add(z3.AtLeast(*(fl + [k])))
    else:
        if k != 0: raise Bad('k>0 without observed domains')
        if not sat([]): raise Bad('base infeasible but status not infeasible')

    # ---- ranges --------------------------------------------------------
    if len(resp['snapshots']) != S: raise Bad('snapshot count')
    for s in range(S):
        rs = resp['snapshots'][s]
        if rs['id'] != inst['snapshots'][s]['id']: raise Bad('snapshot id')
        if len(rs['demands']) != C: raise Bad('demands count')
        for c in range(C):
            lo, hi = rs['demands'][c]
            if type(lo) is not int or type(hi) is not int or lo > hi:
                raise Bad('bad demand range %r' % (rs['demands'][c],))
            if not sat([q[s][c] == lo]): raise Bad('demand min not attained s%d c%d' % (s, c))
            if not sat([q[s][c] == hi]): raise Bad('demand max not attained s%d c%d' % (s, c))
            if sat([q[s][c] < lo]): raise Bad('demand min too high s%d c%d' % (s, c))
            if sat([q[s][c] > hi]): raise Bad('demand max too low s%d c%d' % (s, c))
        if len(rs['links']) != E: raise Bad('links count')
        for e in range(E):
            slo, shi = rs['links'][e]
            vlo = Fraction(slo); vhi = Fraction(shi)
            if vlo > vhi: raise Bad('bad link range')
            if '/' not in slo or '/' not in shi: raise Bad('link not a rational string')
            for part in (slo, shi):
                num, den = part.split('/')
                if int(den) <= 0: raise Bad('non positive denominator')
                f = Fraction(int(num), int(den))
                if '%d/%d' % (f.numerator, f.denominator) != part:
                    raise Bad('not reduced: %s' % part)
            terms = [M['link'][c][e] * q[s][c] for c in range(C) if M['link'][c][e]]
            expr = z3.Sum(terms) if terms else z3.IntVal(0)
            loI = vlo * K; hiI = vhi * K
            if loI.denominator != 1 or hiI.denominator != 1:
                raise Bad('link endpoint not attainable on the K-grid s%d e%d' % (s, e))
            loI = int(loI); hiI = int(hiI)
            if not sat([expr == loI]): raise Bad('link min not attained s%d e%d' % (s, e))
            if not sat([expr == hiI]): raise Bad('link max not attained s%d e%d' % (s, e))
            if sat([expr < loI]): raise Bad('link min too high s%d e%d' % (s, e))
            if sat([expr > hiI]): raise Bad('link max too low s%d e%d' % (s, e))
        # verdict
        ctrl = inst['snapshots'][s]['controller']; tol = inst['snapshots'][s]['tolerance']
        agree = []
        for c in range(C):
            agree.append(q[s][c] >= ctrl[c] - tol); agree.append(q[s][c] <= ctrl[c] + tol)
        a = z3.And(agree) if agree else z3.BoolVal(True)
        yes = sat([a]); no = sat([z3.Not(a)])
        want = 'undetermined' if (yes and no) else ('consistent' if yes else 'inconsistent')
        if rs['verdict'] != want:
            raise Bad('verdict s%d: %s != %s' % (s, rs['verdict'], want))

    # ---- fault sets ----------------------------------------------------
    forced = set(resp['faults']['forced']); possible = set(resp['faults']['possible'])
    for d in inst['domains']:
        fb = M['fvars'].get(d)
        if fb is None:
            if d in possible: raise Bad('unobserved domain in possible: %s' % d)
            if d in forced: raise Bad('unobserved domain in forced: %s' % d)
            continue
        p = sat([fb]); f = not sat([z3.Not(fb)])
        if p != (d in possible): raise Bad('possible mismatch %s' % d)
        if f != (d in forced): raise Bad('forced mismatch %s' % d)
    if not forced <= possible: raise Bad('forced not subset of possible')
    if len(resp['faults']['forced']) != len(forced): raise Bad('dup forced')
    if len(resp['faults']['possible']) != len(possible): raise Bad('dup possible')

    # ---- witnesses -----------------------------------------------------
    def check_w(w, label):
        if len(w['demands']) != S or len(w['links']) != S: raise Bad(label + ': shape')
        if len(w['faults']) != len(set(w['faults'])): raise Bad(label + ': dup faults')
        if len(w['faults']) != k: raise Bad(label + ': fault count %d != %d' % (len(w['faults']), k))
        extra = []
        for s in range(S):
            if len(w['demands'][s]) != C: raise Bad(label + ': demand count')
            if len(w['links'][s]) != E: raise Bad(label + ': link count')
            for c in range(C):
                v = w['demands'][s][c]
                if type(v) is not int: raise Bad(label + ': non int demand')
                extra.append(q[s][c] == v)
        if not sat(extra): raise Bad(label + ': not a feasible explanation')
        # recompute links and faults from the demand matrix, independently
        coms = inst['commodities']; edges = inst['edges']
        eidx = {e['id']: i for i, e in enumerate(edges)}
        faulty = set()
        for s in range(S):
            loads = [Fraction(0)] * E
            metrics = {}
            for ci, c in enumerate(coms):
                v = w['demands'][s][ci]
                metrics[('demand', c['id'])] = Fraction(v)
                W = sum(r['weight'] for r in c['routes'])
                for r in c['routes']:
                    amt = Fraction(v * r['weight'], W)
                    for eid in r['edges']: loads[eidx[eid]] += amt
            for n in inst['nodes']:
                metrics[('ingress', n)] = sum((Fraction(w['demands'][s][ci])
                        for ci, c in enumerate(coms) if c['source'] == n), Fraction(0))
                metrics[('egress', n)] = sum((Fraction(w['demands'][s][ci])
                        for ci, c in enumerate(coms) if c['target'] == n), Fraction(0))
            for ei, e in enumerate(edges):
                metrics[('link', e['id'])] = loads[ei]
                if loads[ei] > e['capacity']: raise Bad(label + ': capacity')
                want = '%d/%d' % (loads[ei].numerator, loads[ei].denominator)
                if w['links'][s][ei] != want:
                    raise Bad(label + ': link %d/%d %r != %r' % (s, ei, w['links'][s][ei], want))
            for o in inst['snapshots'][s]['observations']:
                v = metrics[(o['metric'], o['target'])]
                if not (o['lower'] <= v <= o['upper']):
                    if o['domain'] is None: raise Bad(label + ': trusted violation')
                    faulty.add(o['domain'])
            for c in range(C):
                lo, hi = inst['snapshots'][s]['bounds'][c]
                if not (lo <= w['demands'][s][c] <= hi): raise Bad(label + ': bounds')
        if set(w['faults']) != faulty:
            raise Bad(label + ': fault set %r != %r' % (w['faults'], sorted(faulty)))

    if st not in ('unique', 'ambiguous'): raise Bad('bad status %r' % st)
    singleton = all(rs['demands'][c][0] == rs['demands'][c][1]
                    for rs in resp['snapshots'] for c in range(C))
    if singleton != (st == 'unique'):
        raise Bad('status %s but singleton=%s' % (st, singleton))
    check_w(resp['witness'], 'witness')
    if st == 'unique':
        if resp.get('alternative') is not None: raise Bad('alternative must be null')
    else:
        alt = resp.get('alternative')
        if alt is None: raise Bad('missing alternative')
        check_w(alt, 'alternative')
        if alt['demands'] == resp['witness']['demands']:
            raise Bad('alternative demands identical')
PYEOF
